query:
//Todas as musicas com o gênero 'chill'
Match (t:Track)-[h:HAS_GENRE]->(g:Genre)
WHERE g.genreName = "chill"
RETURN t, h, g
LIMIT 25;

//Quais são as 10 músicas mais populares do gênero 'chill'?
MATCH (t:Track)-[h:HAS_GENRE]->(g:Genre)
WHERE g.genreName = "chill"
RETURN t.trackName AS Musica, t.popularity AS Popularidade, g.genreName AS Genero
ORDER BY t.popularity DESC
LIMIT 10;
